   "en": "Texta Marble is an exclusive collection of premium marbles chosen for their fine grain and rich veining. A metamorphic rock formed from limestone and sensitive to acids, the marble receives a surface treatment that improves stain resistance.",
   "pt": "O Mármore Texta é uma coleção exclusiva de mármores de gama alta escolhidos pelo grão fino e pela riqueza dos veios. Rocha metamórfica formada a partir do calcário e sensível aos ácidos, o mármore recebe um tratamento de superfície que melhora a resistência às nódoas."
