  "description": {
   "fr": "Sensa est la collection de quartzites haut de gamme de Cosentino, protégés en usine par le traitement anti-taches longue durée Sensa Protect. La pierre garde son aspect naturel, supporte les casseroles chaudes, résiste aux UV et se raye moins que le granit. Chaque dalle est unique, aux veinages propres à sa carrière d'origine.",
   "en": "Sensa is Cosentino's premium quartzite line, factory-sealed with the long-lasting Sensa Protect stain treatment. The stone keeps its natural look, tolerates hot pans, resists UV and scratches less easily than granite. Every slab is unique, with veining specific to its quarry of origin.",
   "pt": "Sensa é a gama de quartzito premium da Cosentino, protegida de fábrica com o tratamento antinódoas de longa duração Sensa Protect. A pedra mantém o aspeto natural, aguenta tachos quentes, resiste aos UV e risca menos do que o granito. Cada placa é única, com veios próprios da sua pedreira de origem."
  },
