   "en": "An eco-designed composite made without quartz or porcelain, from recycled minerals bound with plant-based eco-resins. Non-porous and non-yellowing, its pattern runs through the full thickness and it cleans with mild soapy water.",
   "pt": "Compósito ecológico sem quartzo nem porcelânico, fabricado a partir de minerais reciclados ligados por eco-resinas de origem vegetal. Não poroso e resistente ao amarelecimento, o desenho atravessa toda a espessura e limpa-se com água e sabão neutro."
